+export const candidateResolvers = {
+  Query: {
+    candidate: async (_: unknown, { id }: { id: string }, { db, user }) => {
+      const candidate = await db.prepare('SELECT * FROM candidates WHERE id = ?1').bind(id).first();
+      return candidate;
+    },
+  },
+  Candidate: {
+    assessments: async (parent: any, _: unknown, { db }) => {
+      const rows = await db.prepare('SELECT * FROM assessments WHERE candidate_id = ?1').bind(parent.id).all();
+      return rows.results;
+    },
+    scores: async (parent: any, _: unknown, { db }) => {
+      const rows = await db.prepare('SELECT * FROM review_scores WHERE assessment_id IN (SELECT id FROM assessments WHERE candidate_id = ?1)').bind(parent.id).all();
+      return rows.results;
+    },
+  },
+};
